## Sample Solution: Chess Game

### Design Patterns
- **Strategy/Polymorphism**: Each piece type has unique movement rules
- **Command**: Move history for undo/redo
- **Memento**: Board snapshots for state restoration

### Core Classes

```
enum Color { WHITE, BLACK }
enum GameStatus { ACTIVE, CHECK, CHECKMATE, STALEMATE, DRAW }

class Position {
    row: int  // 0-7
    col: int  // 0-7
    isValid(): boolean -> row in [0,7] && col in [0,7]
}

abstract class Piece {
    color: Color
    position: Position
    hasMoved: boolean

    abstract getValidMoves(board: Board): List<Move>
    abstract getSymbol(): char
    canAttack(target: Position, board: Board): boolean
}

class King extends Piece {
    getValidMoves(board):
        // 1 square in any direction
        // Castling if: king & rook havent moved, no pieces between, not through check
        moves = oneSquareMoves + castlingMoves
        return moves.filter { !putsOwnKingInCheck(board) }
}

class Queen extends Piece {
    getValidMoves(board) -> horizontals + verticals + diagonals (until blocked)
}

class Rook extends Piece {
    getValidMoves(board) -> horizontals + verticals (until blocked)
}

class Bishop extends Piece {
    getValidMoves(board) -> diagonals (until blocked)
}

class Knight extends Piece {
    getValidMoves(board) -> L-shaped jumps (can leap over pieces)
}

class Pawn extends Piece {
    getValidMoves(board):
        // Forward 1 (or 2 from starting position)
        // Diagonal capture
        // En passant
        // Promotion handled by Game when reaching last rank
}

class Move {
    piece: Piece
    from: Position
    to: Position
    capturedPiece: Piece  // null if no capture
    isPromotion: boolean
    promotedTo: Piece
    isCastling: boolean
    isEnPassant: boolean
}

class Board {
    grid: Piece[8][8]

    getPiece(pos): Piece
    setPiece(pos, piece): void
    removePiece(pos): Piece
    isUnderAttack(pos, byColor): boolean {
        // Check if any piece of byColor can attack this position
        for each piece of byColor:
            if piece.canAttack(pos) return true
        return false
    }
    getKingPosition(color): Position
    getAllPieces(color): List<Piece>
}

class Game {
    board: Board
    players: Player[2]
    currentTurn: Color
    status: GameStatus
    moveHistory: List<Move>

    makeMove(from, to): boolean {
        piece = board.getPiece(from)
        if (piece.color != currentTurn) return false

        move = createMove(piece, from, to)
        executeMove(move)

        // Check if move puts own king in check (illegal)
        if (isInCheck(currentTurn)) {
            undoMove(move)
            return false
        }

        moveHistory.add(move)
        switchTurn()
        updateGameStatus()
        return true
    }

    updateGameStatus(): void {
        if (isInCheck(currentTurn)) {
            if (hasNoLegalMoves(currentTurn))
                status = CHECKMATE
            else
                status = CHECK
        } else if (hasNoLegalMoves(currentTurn)) {
            status = STALEMATE
        }
    }

    undoLastMove(): void {
        move = moveHistory.removeLast()
        undoMove(move)
        switchTurn()
    }
}
```

### Key Design Decisions
1. Each Piece subclass encapsulates its own movement rules (polymorphism)
2. Move validation: generate move, execute tentatively, check if own king in check, undo if illegal
3. Move object stores captured piece and special move flags for clean undo
4. Board.isUnderAttack() is reused for check detection and castling validation
5. GameStatus updated after every move for immediate check/checkmate detection

## Sample Solution: Snake and Ladder

### Design Patterns
- **Strategy**: Dice rolling strategies
- **Observer**: Notify on game events

### Core Classes

```
class Snake {
    head: int   // start position (higher)
    tail: int   // end position (lower)
    validate() -> assert head > tail
}

class Ladder {
    bottom: int  // start position (lower)
    top: int     // end position (higher)
    validate() -> assert top > bottom
}

interface DiceStrategy {
    roll(): int
}

class SingleDice implements DiceStrategy {
    roll() -> random(1, 6)
}

class DoubleDice implements DiceStrategy {
    roll() -> random(1, 6) + random(1, 6)
}

class Player {
    id: String
    name: String
    position: int = 0  // 0 = not started
}

class Board {
    size: int  // total cells (e.g., 100)
    snakes: Map<int, int>    // head -> tail
    ladders: Map<int, int>   // bottom -> top

    constructor(size, snakes, ladders) {
        validate no conflicts (no overlap between snake heads and ladder tops)
    }

    getNewPosition(position: int): int {
        if (snakes.containsKey(position))
            return snakes.get(position)  // slide down
        if (ladders.containsKey(position))
            return ladders.get(position)  // climb up
        return position  // no change
    }
}

class Game {
    board: Board
    players: List<Player>
    dice: DiceStrategy
    currentPlayerIndex: int
    winner: Player
    isGameOver: boolean

    play(): void {
        while (!isGameOver) {
            player = players.get(currentPlayerIndex)
            takeTurn(player)
            if (!isGameOver)
                currentPlayerIndex = (currentPlayerIndex + 1) % players.size()
        }
    }

    takeTurn(player: Player): void {
        roll = dice.roll()
        newPosition = player.position + roll

        if (newPosition > board.size) {
            return  // cannot move beyond board (exact landing rule)
        }

        if (newPosition == board.size) {
            player.position = newPosition
            winner = player
            isGameOver = true
            return
        }

        // Apply snakes and ladders
        newPosition = board.getNewPosition(newPosition)
        player.position = newPosition
    }
}

class GameBuilder {
    // Fluent builder for configuring the game
    setBoardSize(size): GameBuilder
    addSnake(head, tail): GameBuilder
    addLadder(bottom, top): GameBuilder
    addPlayer(name): GameBuilder
    setDice(strategy): GameBuilder
    build(): Game
}
```

### Key Design Decisions
1. Board stores snakes/ladders as position mappings for O(1) lookup
2. Strategy pattern makes dice configurable (single, double, loaded)
3. Separate validation ensures no conflicting snake/ladder positions
4. Builder pattern for fluent game configuration
5. Game loop is simple: roll, move, check transport, check win, next player

## Sample Solution: Splitwise

### Design Patterns
- **Strategy**: Split calculation (equal, exact, percentage)
- **Observer**: Notify users of new expenses and settlements

### Core Classes

```
class User {
    id: String
    name: String
    email: String
}

class Group {
    id: String
    name: String
    members: List<User>
    expenses: List<Expense>

    getBalances(): Map<String, Map<String, double>>  // userId -> (userId -> amount)
    getSimplifiedDebts(): List<Transaction>
}

class Expense {
    id: String
    description: String
    amount: double
    paidBy: User
    group: Group
    splits: List<Split>
    createdAt: DateTime
}

abstract class Split {
    user: User
    abstract getAmount(totalAmount: double, participantCount: int): double
}

class EqualSplit extends Split {
    getAmount(total, count) -> total / count
}

class ExactSplit extends Split {
    exactAmount: double
    getAmount(total, count) -> exactAmount
}

class PercentSplit extends Split {
    percentage: double
    getAmount(total, count) -> total * percentage / 100
}

class BalanceSheet {
    // balances[A][B] = amount A owes B (positive = A owes B, negative = B owes A)
    balances: Map<String, Map<String, double>>

    addExpense(expense: Expense): void {
        payer = expense.paidBy.id
        for split in expense.splits:
            if (split.user.id == payer) continue
            amount = split.getAmount(expense.amount, expense.splits.size)
            // split.user owes payer
            balances[split.user.id][payer] += amount
            balances[payer][split.user.id] -= amount
        }
    }

    getNetBalances(): Map<String, double> {
        // net[user] = total owed to user - total user owes
        net = {}
        for each pair: net[user] = sum of all balances involving user
        return net
    }
}

class DebtSimplifier {
    simplify(netBalances: Map<String, double>): List<Transaction> {
        creditors = PriorityQueue(maxHeap)  // users owed money
        debtors = PriorityQueue(maxHeap)    // users who owe money

        for (user, net) in netBalances:
            if (net > 0) creditors.add(user, net)
            if (net < 0) debtors.add(user, -net)

        transactions = []
        while (!creditors.isEmpty()):
            creditor = creditors.poll()
            debtor = debtors.poll()
            settled = min(creditor.amount, debtor.amount)
            transactions.add(Transaction(debtor -> creditor, settled))
            remaining_creditor = creditor.amount - settled
            remaining_debtor = debtor.amount - settled
            if (remaining_creditor > 0) creditors.add(creditor, remaining_creditor)
            if (remaining_debtor > 0) debtors.add(debtor, remaining_debtor)

        return transactions
    }
}

class SplitwiseService {
    users: Map<String, User>
    groups: Map<String, Group>
    balanceSheets: Map<String, BalanceSheet>  // per group

    addExpense(groupId, paidBy, amount, splits): Expense
    settleDebt(fromUser, toUser, amount): void
    getSimplifiedDebts(groupId): List<Transaction>
    getUserBalance(userId): Map<String, double>  // per-user net across all groups
}
```

### Key Design Decisions
1. Strategy pattern for split types validates that shares sum to total
2. BalanceSheet tracks pairwise debts for accurate individual tracking
3. Debt simplification uses greedy approach: O(N log N) to minimize transactions
4. Net balance calculation: convert pairwise debts to per-user net amounts
5. Use cents (long) instead of dollars (double) to avoid floating point errors

## Sample Solution: LRU Cache

### Core Classes

```
class Node {
    key: int
    value: int
    prev: Node
    next: Node
}

class DoublyLinkedList {
    head: Node  // dummy head
    tail: Node  // dummy tail

    constructor() {
        head = new Node()
        tail = new Node()
        head.next = tail
        tail.prev = head
    }

    addToHead(node): void {
        node.prev = head
        node.next = head.next
        head.next.prev = node
        head.next = node
    }

    removeNode(node): void {
        node.prev.next = node.next
        node.next.prev = node.prev
    }

    removeTail(): Node {
        node = tail.prev
        removeNode(node)
        return node
    }

    moveToHead(node): void {
        removeNode(node)
        addToHead(node)
    }
}

class LRUCache {
    capacity: int
    map: HashMap<int, Node>
    list: DoublyLinkedList

    get(key: int): int {
        if (!map.containsKey(key)) return -1
        node = map.get(key)
        list.moveToHead(node)  // mark as recently used
        return node.value
    }

    put(key: int, value: int): void {
        if (map.containsKey(key)) {
            node = map.get(key)
            node.value = value
            list.moveToHead(node)
        } else {
            node = new Node(key, value)
            map.put(key, node)
            list.addToHead(node)
            if (map.size() > capacity) {
                lru = list.removeTail()
                map.remove(lru.key)
            }
        }
    }
}
```

### Key Design Decisions
1. Dummy head/tail nodes simplify edge cases (no null checks)
2. HashMap stores key -> Node reference for O(1) lookup
3. Doubly linked list maintains access order for O(1) move/remove
4. Node stores key so we can remove from map during eviction

## Sample Solution: Tic Tac Toe

### Core Classes

```
enum Mark { X, O, EMPTY }
enum GameStatus { IN_PROGRESS, X_WINS, O_WINS, DRAW }

class Player {
    name: String
    mark: Mark
}

class Board {
    size: int
    grid: Mark[][]
    moveCount: int

    // O(1) win detection trackers
    rowCounts: int[][]   // [row][playerIndex]
    colCounts: int[][]   // [col][playerIndex]
    diagCount: int[]     // [playerIndex]
    antiDiagCount: int[] // [playerIndex]

    constructor(size) {
        grid = new Mark[size][size] // all EMPTY
        // initialize count arrays to 0
    }

    placeMark(row, col, mark): boolean {
        if (grid[row][col] != EMPTY) return false
        grid[row][col] = mark
        moveCount++
        return true
    }

    isFull(): boolean -> moveCount == size * size
}

class Game {
    board: Board
    players: Player[2]
    currentPlayerIndex: int
    status: GameStatus

    makeMove(row, col): GameStatus {
        player = players[currentPlayerIndex]
        if (!board.placeMark(row, col, player.mark))
            throw "Invalid move"

        // O(1) win check using counts
        pIdx = currentPlayerIndex
        board.rowCounts[row][pIdx]++
        board.colCounts[col][pIdx]++
        if (row == col) board.diagCount[pIdx]++
        if (row + col == board.size - 1) board.antiDiagCount[pIdx]++

        if (board.rowCounts[row][pIdx] == board.size ||
            board.colCounts[col][pIdx] == board.size ||
            board.diagCount[pIdx] == board.size ||
            board.antiDiagCount[pIdx] == board.size) {
            status = player.mark == X ? X_WINS : O_WINS
        } else if (board.isFull()) {
            status = DRAW
        } else {
            currentPlayerIndex = 1 - currentPlayerIndex
        }
        return status
    }

    reset(): void -> new board, reset status
}
```

### Key Design Decisions
1. O(1) win detection by tracking row/col/diagonal counts per player
2. Board is decoupled from Game for reusability
3. NxN generalization: win requires N marks in a row (same logic scales)
4. MoveCount avoids scanning entire grid to check for draw

## Sample Solution: Elevator System

### Design Patterns
- **Strategy**: Scheduling algorithm (SCAN, LOOK, SSTF)
- **State**: Elevator states (Idle, MovingUp, MovingDown)
- **Observer**: Notify controller when elevator completes a request

### Core Classes

```
enum Direction { UP, DOWN, IDLE }

class Request {
    sourceFloor: int
    destinationFloor: int
    direction: Direction
    timestamp: long
}

class Elevator {
    id: int
    currentFloor: int
    direction: Direction
    upStops: TreeSet<int>      // sorted set of floors to visit going up
    downStops: TreeSet<int>    // sorted set of floors to visit going down
    state: ElevatorState

    addStop(floor): void {
        if (floor > currentFloor) upStops.add(floor)
        else if (floor < currentFloor) downStops.add(floor)
    }

    move(): void {
        if (direction == UP) {
            if (!upStops.isEmpty()) {
                currentFloor = upStops.pollFirst()
                openDoors()
            } else if (!downStops.isEmpty()) {
                direction = DOWN
                currentFloor = downStops.pollLast()
                openDoors()
            } else {
                direction = IDLE
            }
        }
        // symmetric for DOWN
    }

    isIdle(): boolean -> direction == IDLE
    getDistance(floor): int -> abs(currentFloor - floor)
}

interface SchedulingStrategy {
    selectElevator(elevators: List<Elevator>, request: Request): Elevator
}

class SCANStrategy implements SchedulingStrategy {
    selectElevator(elevators, request):
        // Prefer: elevator moving toward request floor in same direction
        // Then: idle elevator nearest to request
        // Then: any nearest elevator
        best = null
        bestScore = MAX_INT
        for elevator in elevators:
            score = calculateScore(elevator, request)
            if (score < bestScore)
                best = elevator; bestScore = score
        return best
}

class ElevatorController {
    elevators: List<Elevator>
    strategy: SchedulingStrategy

    handleExternalRequest(floor, direction): void {
        elevator = strategy.selectElevator(elevators, new Request(floor, direction))
        elevator.addStop(floor)
    }

    handleInternalRequest(elevatorId, floor): void {
        elevator = getElevator(elevatorId)
        elevator.addStop(floor)
    }

    step(): void {
        for elevator in elevators:
            elevator.move()
    }
}
```

### Key Design Decisions
1. TreeSet for stops gives O(log N) insertion and O(1) next-stop retrieval
2. Separate upStops/downStops avoids re-sorting when direction changes
3. Strategy pattern makes scheduling algorithm pluggable
4. Controller assigns external requests; internal requests go directly to elevator

## Sample Solution: Pub Sub System

### Design Patterns
- **Observer**: Subscribers observe topics for new messages
- **Mediator**: Broker mediates all communication

### Core Classes

```
class Message {
    id: String
    topic: String
    payload: Object
    attributes: Map<String, String>
    timestamp: DateTime
}

interface Subscriber {
    id: String
    onMessage(message: Message): void
}

class Topic {
    name: String
    subscribers: Set<Subscriber>

    addSubscriber(sub): void
    removeSubscriber(sub): void
    publish(message): void {
        for sub in subscribers:
            sub.onMessage(message)
    }
}

class Publisher {
    id: String
    broker: Broker

    publish(topicName, payload, attributes): void {
        message = new Message(uuid(), topicName, payload, attributes, now())
        broker.publish(topicName, message)
    }
}

interface MessageFilter {
    matches(message: Message): boolean
}

class AttributeFilter implements MessageFilter {
    key: String
    value: String
    matches(msg) -> msg.attributes.get(key).equals(value)
}

class FilteredSubscriber implements Subscriber {
    delegate: Subscriber
    filters: List<MessageFilter>

    onMessage(message): void {
        if (filters.all { it.matches(message) })
            delegate.onMessage(message)
    }
}

class Broker {
    topics: Map<String, Topic>

    createTopic(name): Topic
    deleteTopic(name): void
    publish(topicName, message): void {
        topic = topics.get(topicName)
        if (topic != null) topic.publish(message)
    }
    subscribe(topicName, subscriber): void {
        topic = topics.get(topicName)
        topic.addSubscriber(subscriber)
    }
    unsubscribe(topicName, subscriber): void
}
```

### Key Design Decisions
1. Broker acts as Mediator - publishers and subscribers never reference each other
2. FilteredSubscriber uses Decorator pattern to add filtering without modifying Subscriber
3. Topic owns subscriber list for efficient fan-out
4. Message attributes enable flexible filtering without changing message structure

## Sample Solution: ATM

### Design Patterns
- **State Pattern**: ATM states (NoCard, HasCard, Authenticated, TransactionInProgress)
- **Chain of Responsibility**: Withdrawal validation chain

### Core Classes

```
interface ATMState {
    insertCard(card: Card): void
    enterPin(pin: String): void
    selectTransaction(type: TransactionType): void
    executeTransaction(amount: double): void
    ejectCard(): void
}

class NoCardState implements ATMState {
    insertCard(card) -> validate card, transition to HasCard
    enterPin(pin) -> throw "Insert card first"
    // other methods throw similar errors
}

class HasCardState implements ATMState {
    enterPin(pin) -> bank.validatePin(card, pin) -> if valid: Authenticated, else: retry/eject
}

class AuthenticatedState implements ATMState {
    selectTransaction(type) -> transition to TransactionInProgress
    ejectCard() -> transition to NoCard
}

class Account {
    id: String
    balance: double
    dailyWithdrawn: double
    dailyLimit: double
    transactions: List<Transaction>
}

class CashDispenser {
    denominations: Map<int, int>  // value -> count (e.g., 100->50, 50->100, 20->200)

    canDispense(amount): boolean
    dispense(amount): Map<int, int> {
        // Greedy: largest denominations first
        result = {}
        remaining = amount
        for denom in sorted(denominations.keys, DESC):
            count = min(remaining / denom, denominations[denom])
            if (count > 0):
                result[denom] = count
                remaining -= count * denom
        if (remaining > 0) throw "Cannot dispense exact amount"
        // deduct from inventory
        return result
    }
}

// Chain of Responsibility for withdrawal validation
abstract class WithdrawalValidator {
    next: WithdrawalValidator
    validate(account, amount): void {
        doValidate(account, amount)
        if (next != null) next.validate(account, amount)
    }
    abstract doValidate(account, amount): void
}

class BalanceValidator extends WithdrawalValidator {
    doValidate(acct, amt) -> if (acct.balance < amt) throw "Insufficient funds"
}

class DailyLimitValidator extends WithdrawalValidator {
    doValidate(acct, amt) -> if (acct.dailyWithdrawn + amt > acct.dailyLimit) throw "Daily limit exceeded"
}

class ATMCashValidator extends WithdrawalValidator {
    doValidate(acct, amt) -> if (!dispenser.canDispense(amt)) throw "ATM cannot dispense this amount"
}

class ATM {
    state: ATMState
    bank: BankService
    dispenser: CashDispenser
    validationChain: WithdrawalValidator  // balance -> dailyLimit -> atmCash
    currentCard: Card
    currentAccount: Account
}
```

### Key Design Decisions
1. State pattern prevents invalid operations (cant enter PIN without card)
2. Validation chain is extensible - add new validators without modifying existing
3. Greedy denomination algorithm for cash dispensing
4. Bank service is external - ATM communicates via interface

## Sample Solution: Hotel Management System

### Design Patterns
- **Strategy**: Pricing strategies (standard, peak, holiday)
- **Factory Method**: Room creation by type

### Core Classes

```
enum RoomType { SINGLE, DOUBLE, DELUXE, SUITE }
enum BookingStatus { CONFIRMED, CHECKED_IN, CHECKED_OUT, CANCELLED }

class Room {
    id: String
    type: RoomType
    floor: int
    capacity: int
    basePrice: double
    isClean: boolean
}

class Guest {
    id: String
    name: String
    email: String
    phone: String
}

class Booking {
    id: String
    guest: Guest
    room: Room
    checkIn: Date
    checkOut: Date
    status: BookingStatus
    totalAmount: double
    payment: Payment
}

interface PricingStrategy {
    calculatePrice(room: Room, checkIn: Date, checkOut: Date): double
}

class StandardPricing implements PricingStrategy {
    calculate(room, in, out) -> room.basePrice * numberOfNights
}

class SeasonalPricing implements PricingStrategy {
    peakMultiplier: double  // e.g., 1.5
    peakDates: Set<DateRange>
    calculate(room, in, out) -> sum per night (peak or standard rate)
}

class Hotel {
    rooms: List<Room>
    bookings: List<Booking>
    pricing: PricingStrategy

    searchAvailable(checkIn, checkOut, type): List<Room> {
        return rooms.filter { room ->
            room.type == type &&
            bookings.none { b ->
                b.room == room &&
                b.status != CANCELLED &&
                datesOverlap(b.checkIn, b.checkOut, checkIn, checkOut)
            }
        }
    }

    createBooking(guest, room, checkIn, checkOut): Booking {
        if (!isAvailable(room, checkIn, checkOut)) throw "Room not available"
        amount = pricing.calculatePrice(room, checkIn, checkOut)
        booking = new Booking(guest, room, checkIn, checkOut, CONFIRMED, amount)
        bookings.add(booking)
        return booking
    }

    cancel(bookingId): double {
        booking = findBooking(bookingId)
        refund = cancellationPolicy.calculateRefund(booking)
        booking.status = CANCELLED
        return refund
    }

    checkIn(bookingId): void {
        booking = findBooking(bookingId)
        booking.status = CHECKED_IN
    }

    checkOut(bookingId): Payment {
        booking = findBooking(bookingId)
        booking.status = CHECKED_OUT
        booking.room.isClean = false  // needs housekeeping
        return processPayment(booking)
    }
}
```

### Key Design Decisions
1. Availability check: no overlapping confirmed bookings for a room in date range
2. Pricing strategy is pluggable (seasonal, dynamic, promotional)
3. Cancellation policy returns refund amount based on timing
4. Room cleanliness tracked for housekeeping workflow

## Sample Solution: Movie Ticket Booking (BookMyShow)

### Design Patterns
- **State**: Seat status lifecycle (Available -> Locked -> Booked)
- **Strategy**: Pricing (weekday, weekend, holiday, premium)
- **Observer**: Notify on seat availability changes

### Core Classes

```
class Movie {
    id: String
    title: String
    genre: Genre
    language: String
    duration: int  // minutes
}

class Theater {
    id: String
    name: String
    city: String
    screens: List<Screen>
}

class Screen {
    id: String
    theater: Theater
    name: String  // "Screen 1"
    seatLayout: List<List<Seat>>  // rows x cols
    totalCapacity: int
}

class Show {
    id: String
    movie: Movie
    screen: Screen
    startTime: DateTime
    endTime: DateTime
    pricing: Map<SeatCategory, double>
    showSeats: List<ShowSeat>  // per-show seat availability
}

class Seat {
    id: String
    row: String  // "A", "B", ...
    number: int
    category: SeatCategory  // REGULAR, PREMIUM, VIP
}

class ShowSeat {
