    seat: Seat
    status: SeatStatus  // AVAILABLE, LOCKED, BOOKED
    lockedBy: String
    lockExpiry: DateTime
    price: double
}

class Booking {
    id: String
    user: User
    show: Show
    seats: List<ShowSeat>
    totalAmount: double
    status: BookingStatus
    payment: Payment
    tickets: List<Ticket>
    bookedAt: DateTime
}

class SeatLockManager {
    LOCK_DURATION = 8 minutes

    lockSeats(showId, seatIds, userId): boolean {
        synchronized(show) {
            // Verify all seats AVAILABLE
            for seatId in seatIds:
                showSeat = findShowSeat(showId, seatId)
                if (showSeat.status != AVAILABLE) return false

            // Lock all seats atomically
            for seatId in seatIds:
                showSeat = findShowSeat(showId, seatId)
                showSeat.status = LOCKED
                showSeat.lockedBy = userId
                showSeat.lockExpiry = now() + LOCK_DURATION
            return true
        }
    }

    confirmBooking(showId, seatIds, userId): void {
        synchronized(show) {
            for seatId in seatIds:
                showSeat = findShowSeat(showId, seatId)
                assert showSeat.lockedBy == userId
                showSeat.status = BOOKED
        }
    }

    // Scheduled every minute
    releaseExpiredLocks(): void {
        for each show -> for each showSeat:
            if (status == LOCKED && lockExpiry < now()):
                showSeat.status = AVAILABLE
                showSeat.lockedBy = null
    }
}

class BookingService {
    seatLockManager: SeatLockManager
    paymentService: PaymentService

    startBooking(userId, showId, seatIds): BookingSession {
        if (!seatLockManager.lockSeats(showId, seatIds, userId))
            throw "Seats no longer available"
        return new BookingSession(userId, showId, seatIds, totalPrice)
    }

    completeBooking(session, paymentInfo): Booking {
        payment = paymentService.process(paymentInfo, session.totalPrice)
        seatLockManager.confirmBooking(session.showId, session.seatIds, session.userId)
        booking = createBooking(session, payment)
        return booking
    }
}
```

### Key Design Decisions
1. ShowSeat separates per-show availability from physical Seat definition
2. Synchronized locking on Show object prevents race conditions
3. Lock expiry with scheduled cleanup handles abandoned bookings
4. Atomic multi-seat locking: all-or-nothing to prevent partial bookings
5. Theater > Screen > Show hierarchy models real-world structure

