    items: List<OrderItem>
    status: OrderStatus
    totalAmount: double
    payment: Payment
    shipment: Shipment
    shippingAddress: Address
    createdAt: DateTime

    cancel(): void {
        if (status == SHIPPED || status == DELIVERED)
            throw "Cannot cancel shipped order"
        status = CANCELLED
    }
}

class OrderItem {
    product: Product
    quantity: int
    priceAtOrder: double  // snapshot of price at order time
}

interface PaymentStrategy {
    processPayment(amount: double, details: PaymentDetails): PaymentResult
    processRefund(paymentId: String, amount: double): RefundResult
}

class CreditCardPayment implements PaymentStrategy { ... }
class WalletPayment implements PaymentStrategy { ... }
class CODPayment implements PaymentStrategy { ... }

