    id: String
    order: Order
    trackingNumber: String
    carrier: String
    status: ShipmentStatus
    estimatedDelivery: DateTime
}

class OrderService {
    inventory: Inventory
    paymentStrategies: Map<PaymentType, PaymentStrategy>
    observers: List<OrderObserver>

    placeOrder(cart, customer, paymentType, address): Order {
        // 1. Validate and reserve inventory
        for item in cart.items:
            if (!inventory.reserve(item.productId, item.quantity))
                throw "Out of stock: " + item.product.name

        // 2. Create order
        order = createOrderFromCart(cart, customer, address)

        // 3. Process payment
        strategy = paymentStrategies.get(paymentType)
        payment = strategy.processPayment(order.totalAmount, ...)
        order.payment = payment
        order.status = CONFIRMED

        // 4. Clear cart
        cart.clear()

        // 5. Notify
        notifyObservers(OrderEvent.CREATED, order)
        return order
    }

    cancelOrder(orderId): void {
        order = findOrder(orderId)
        order.cancel()
        // Release inventory
        for item in order.items:
            inventory.release(item.productId, item.quantity)
        // Process refund
        paymentStrategy.processRefund(order.payment.id, order.totalAmount)
    }
}
```

### Key Design Decisions
1. Inventory reservation at order time (not at add-to-cart)
2. Price snapshot in OrderItem protects against price changes after ordering
3. Strategy pattern makes payment methods pluggable
4. Order status transitions are validated (cant skip states)
5. Cart is separate from Order - cart is mutable, order is immutable once placed
6. Cancellation releases inventory and triggers refund

## Sample Solution: Digital Wallet Service

### Design Patterns
- **Command**: Encapsulate wallet operations for audit trail
- **Observer**: Notify users on transactions

### Core Classes

```
enum TransactionType { DEPOSIT, WITHDRAWAL, TRANSFER_SENT, TRANSFER_RECEIVED }
enum TransactionStatus { PENDING, COMPLETED, FAILED, REVERSED }

class Wallet {
    id: String
    userId: String
    balance: double  // guarded by lock
    lock: ReentrantLock

    credit(amount): void {
        lock.lock()
        try { balance += amount }
        finally { lock.unlock() }
    }

    debit(amount): void {
        lock.lock()
        try {
            if (balance < amount) throw "Insufficient funds"
            balance -= amount
        }
        finally { lock.unlock() }
    }
}

class Transaction {
    id: String
    type: TransactionType
    fromWallet: String
    toWallet: String
    amount: double
    status: TransactionStatus
    timestamp: DateTime
    description: String
}

class TransferService {
    wallets: Map<String, Wallet>
    transactions: List<Transaction>
    observers: List<TransactionObserver>

    transfer(fromId, toId, amount): Transaction {
        from = wallets.get(fromId)
        to = wallets.get(toId)
        first = fromId < toId ? from : to
        second = fromId < toId ? to : from
        first.lock.lock()
        second.lock.lock()
        try {
            from.debit(amount)
            to.credit(amount)
            txn = logTransaction(TRANSFER, from, to, amount, COMPLETED)
            notifyObservers(txn)
            return txn
        } catch (e) {
            txn = logTransaction(TRANSFER, from, to, amount, FAILED)
            throw e
        } finally {
            second.lock.unlock()
            first.lock.unlock()
        }
    }

    deposit(walletId, amount): Transaction
    withdraw(walletId, amount): Transaction
    getHistory(walletId, filters): List<Transaction>
}
```

### Key Design Decisions
1. Lock ordering (by wallet ID) prevents deadlocks in transfers
2. Transactions are immutable records for audit trail
3. ReentrantLock per wallet for fine-grained concurrency
4. Failed transfers are logged with FAILED status (never deleted)
5. Observer decouples notifications from transaction logic

## Sample Solution: Online Auction System

### Design Patterns
- **Observer**: Notify outbid users and winner
- **State**: Auction lifecycle (Scheduled, Active, Closed)

### Core Classes

```
enum AuctionStatus { SCHEDULED, ACTIVE, CLOSED, CANCELLED }

class Item {
    id: String
    name: String
    description: String
    seller: User
}

class Bid {
    id: String
    bidder: User
    amount: double
    timestamp: DateTime
}

class Auction {
    id: String
    item: Item
    startPrice: double
    minIncrement: double
    startTime: DateTime
    endTime: DateTime
    status: AuctionStatus
    bids: List<Bid>
    highestBid: Bid
    winner: User
    lock: ReentrantLock

    placeBid(user, amount): Bid {
        lock.lock()
        try {
            if (status != ACTIVE) throw "Auction not active"
            if (user == item.seller) throw "Cannot bid on own item"
            minRequired = highestBid ? highestBid.amount + minIncrement : startPrice
            if (amount < minRequired) throw "Bid too low"
            previousHighest = highestBid?.bidder
            bid = new Bid(user, amount, now())
            bids.add(bid)
            highestBid = bid
            return bid
        } finally { lock.unlock() }
    }

    close(): void {
        lock.lock()
        try {
            status = CLOSED
            winner = highestBid?.bidder
        } finally { lock.unlock() }
    }
}

class AuctionService {
    auctions: Map<String, Auction>
    scheduler: ScheduledExecutorService
    observers: List<AuctionObserver>

    createAuction(item, startPrice, minIncrement, start, end): Auction {
        auction = new Auction(...)
        scheduler.schedule(() -> auction.activate(), start)
        scheduler.schedule(() -> closeAuction(auction.id), end)
        return auction
    }

    placeBid(auctionId, user, amount): void {
        auction = auctions.get(auctionId)
        previousHighest = auction.highestBid?.bidder
        bid = auction.placeBid(user, amount)
        if (previousHighest != null)
            notifyOutbid(previousHighest, auction)
    }

    closeAuction(auctionId): void {
        auction = auctions.get(auctionId)
        auction.close()
        if (auction.winner != null)
            notifyWinner(auction.winner, auction)
    }
}
```

### Key Design Decisions
1. Lock per auction for thread-safe bid placement
2. Scheduler handles automatic start/close at configured times
3. Bid validation inside Auction ensures invariants
4. Bids are immutable and irrevocable once placed
5. Observer decouples notification from bid logic

