## Sample Solution: Notification System

### Design Patterns
- **Strategy**: Channel-specific delivery (email, SMS, push)
- **Template Method**: Standard delivery pipeline
- **Observer**: Events trigger notifications

### Core Classes

```
enum Priority { CRITICAL, HIGH, NORMAL, LOW }
enum DeliveryStatus { PENDING, SENT, DELIVERED, FAILED }
enum ChannelType { EMAIL, SMS, PUSH, IN_APP }

class Template {
    id: String
    name: String
    channelType: ChannelType
    subject: String
    body: String     // with {{placeholders}}

    render(variables: Map<String, String>): String {
        result = body
        for (key, value) in variables:
            result = result.replace("{{" + key + "}}", value)
        return result
    }
}

class UserPreference {
    userId: String
    enabledChannels: Set<ChannelType>
    quietHoursStart: Time
    quietHoursEnd: Time
}

abstract class NotificationChannel {
    type: ChannelType
    retryPolicy: RetryPolicy

    final deliver(notification: Notification): DeliveryStatus {
        validate(notification)
        content = renderContent(notification)
        status = send(content, notification.recipient)
        track(notification, status)
        return status
    }

    abstract send(content, recipient): DeliveryStatus
}

class EmailChannel extends NotificationChannel {
    send(content, recipient) -> emailService.send(recipient.email, content)
}

class SMSChannel extends NotificationChannel {
    send(content, recipient) -> smsGateway.send(recipient.phone, content)
}

class PushChannel extends NotificationChannel {
    send(content, recipient) -> pushService.send(recipient.deviceToken, content)
}

class RetryPolicy {
    maxRetries: int = 3
    baseDelayMs: long = 1000
    getDelay(attempt): long -> baseDelayMs * 2^attempt
    shouldRetry(attempt, error): boolean -> attempt < maxRetries
}

class Notification {
    id: String
    recipient: User
    template: Template
    variables: Map<String, String>
    channels: List<ChannelType>
    priority: Priority
    status: Map<ChannelType, DeliveryStatus>
    retryCount: Map<ChannelType, int>
}

class NotificationService {
    channels: Map<ChannelType, NotificationChannel>
    queue: PriorityQueue<Notification>
    preferences: Map<String, UserPreference>

    send(userId, templateId, variables, priority): void {
        prefs = preferences.get(userId)
        enabledChannels = resolveChannels(prefs, priority)
        notification = new Notification(userId, template, variables, enabledChannels, priority)
        queue.add(notification)
    }

    processQueue(): void {
        notification = queue.poll()
        for channelType in notification.channels:
            channel = channels.get(channelType)
            status = channel.deliver(notification)
            if (status == FAILED && retryPolicy.shouldRetry(...)):
                scheduleRetry(notification, channelType)
    }

    resolveChannels(prefs, priority): List<ChannelType> {
        if (priority == CRITICAL) return ALL_CHANNELS
        return prefs.enabledChannels
    }
}
```

### Key Design Decisions
1. Template Method ensures consistent pipeline (validate -> render -> send -> track)
2. Priority queue delivers critical notifications first
3. Exponential backoff prevents hammering failed channels
4. Critical notifications bypass user preferences
5. Per-channel delivery status tracking for debugging

## Sample Solution: In-Memory File System

### Design Patterns
- **Composite**: File and Directory share FileSystemEntry interface

### Core Classes

```
abstract class FileSystemEntry {
    name: String
    parent: Directory
    createdAt: DateTime
    modifiedAt: DateTime

    getPath(): String {
        if (parent == null) return "/"
        parentPath = parent.getPath()
        return parentPath.equals("/") ? "/" + name : parentPath + "/" + name
    }

    abstract isDirectory(): boolean
    abstract getSize(): long
}

class File extends FileSystemEntry {
    content: String

    isDirectory() -> false
    getSize() -> content.length
    read(): String -> content
    write(data: String): void {
        content = data
        modifiedAt = now()
    }
    append(data: String): void {
        content += data
        modifiedAt = now()
    }
}

class Directory extends FileSystemEntry {
    children: Map<String, FileSystemEntry>

    isDirectory() -> true
    getSize() -> children.values.sum { it.getSize() }

    addChild(entry: FileSystemEntry): void {
        if (children.containsKey(entry.name)) throw "Already exists"
        children.put(entry.name, entry)
        entry.parent = this
    }

    removeChild(name: String): FileSystemEntry {
        return children.remove(name)
    }

    getChild(name: String): FileSystemEntry {
        return children.get(name)
    }

    list(): List<String> -> children.keys sorted
}

class FileSystem {
    root: Directory
    currentDir: Directory

    constructor() {
        root = new Directory("/", null)
        currentDir = root
    }

    resolvePath(path: String): FileSystemEntry {
        if (path.startsWith("/"))
            current = root
        else
            current = currentDir

        parts = path.split("/").filter(not empty)
        for part in parts:
            if (part == ".") continue
            if (part == "..") {
                current = current.parent ?? root
                continue
            }
            child = current.getChild(part)
            if (child == null) throw "Path not found: " + path
            current = child
        return current
    }

    mkdir(path: String): void
    mkdirp(path: String): void
    touch(path: String): File
    write(path: String, content: String): void
    read(path: String): String
    ls(path: String): List<String>
    cd(path: String): void { currentDir = resolvePath(path) }
    pwd(): String { return currentDir.getPath() }
    rm(path: String): void
}
```

### Key Design Decisions
1. Composite pattern: File and Directory both extend FileSystemEntry
2. Parent reference enables getPath() and .. navigation
3. Path resolution handles absolute (/), relative, ., and .. uniformly
4. Map<name, entry> in Directory gives O(1) child lookup
5. Recursive getSize() on directories sums all descendant file sizes

## Sample Solution: URL Shortener

### Design Patterns
- **Strategy**: Code generation algorithm (base62, hash, random)

### Core Classes

```
class URLMapping {
    shortCode: String
    originalUrl: String
    createdAt: DateTime
    expiresAt: DateTime  // null = never expires
    clickCount: AtomicLong
    createdBy: String

    isExpired(): boolean -> expiresAt != null && now() > expiresAt
}

interface CodeGenerator {
    generate(url: String): String
}

class Base62Generator implements CodeGenerator {
    counter: AtomicLong
    ALPHABET = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789"

    generate(url): String {
        id = counter.incrementAndGet()
        return toBase62(id)
    }

    toBase62(num): String {
        result = ""
        while (num > 0):
            result = ALPHABET[num % 62] + result
            num /= 62
        return result.padLeft(6)
    }
}

class HashGenerator implements CodeGenerator {
    generate(url): String {
        hash = MD5(url + timestamp + random)
        return base62Encode(hash).substring(0, 7)
    }
}

class ClickEvent {
    shortCode: String
    timestamp: DateTime
    referrer: String
    userAgent: String
    ipAddress: String
}

class AnalyticsTracker {
    clicks: Map<String, List<ClickEvent>>

    recordClick(shortCode, request): void
    getStats(shortCode): ClickStats
}

class URLShortener {
    mappings: Map<String, URLMapping>
    reverseMap: Map<String, String>
    generator: CodeGenerator
    analytics: AnalyticsTracker

    shorten(originalUrl, ttlDays): String {
        if (reverseMap.containsKey(originalUrl))
            return reverseMap.get(originalUrl)

        code = generator.generate(originalUrl)
        while (mappings.containsKey(code)):
            code = generator.generate(originalUrl + random())

        mapping = new URLMapping(code, originalUrl, now(), ttlDays ? now() + ttlDays : null)
        mappings.put(code, mapping)
        reverseMap.put(originalUrl, code)
        return code
    }

    redirect(shortCode, request): String {
        mapping = mappings.get(shortCode)
        if (mapping == null || mapping.isExpired())
            throw "URL not found"
        analytics.recordClick(shortCode, request)
        mapping.clickCount.incrementAndGet()
        return mapping.originalUrl
    }
}
```

### Key Design Decisions
1. Base62 counter-based approach gives guaranteed uniqueness (no collisions)
2. Hash-based approach needs collision detection and retry
3. Reverse map deduplicates: same URL always gets same short code
4. TTL checked at redirect time (lazy expiry)
5. Analytics tracked asynchronously to not slow down redirects
6. AtomicLong for thread-safe click counting

