```
class Song {
    id: String
    title: String
    artist: Artist
    album: Album
    duration: int  // seconds
    genre: String
    playCount: long
}

class Album {
    id: String
    title: String
    artist: Artist
    songs: List<Song>
    releaseDate: Date
}

class Artist {
    id: String
    name: String
    albums: List<Album>
    followers: int
}

class Playlist {
    id: String
    name: String
    owner: User
    songs: List<Song>
    isPublic: boolean
    followers: List<User>

    addSong(song): void { songs.add(song); notifyFollowers() }
    removeSong(songId): void
    reorder(fromIndex, toIndex): void
}

enum RepeatMode { OFF, ONE, ALL }

class PlayQueue {
    originalOrder: List<Song>
    currentQueue: List<Song>  // may be shuffled
    currentIndex: int
    isShuffled: boolean
    repeatMode: RepeatMode

    current(): Song -> currentQueue[currentIndex]

    next(): Song {
        if (repeatMode == ONE) return current()
        currentIndex++
        if (currentIndex >= currentQueue.size) {
            if (repeatMode == ALL) currentIndex = 0
            else return null  // queue ended
        }
        return current()
    }

    previous(): Song {
        currentIndex = max(0, currentIndex - 1)
        return current()
    }

    shuffle(): void {
        isShuffled = true
        remaining = currentQueue.subList(currentIndex + 1)
        Collections.shuffle(remaining)
    }

    unshuffle(): void {
        currentSong = current()
        currentQueue = new ArrayList(originalOrder)
        currentIndex = currentQueue.indexOf(currentSong)
        isShuffled = false
    }

    addToQueue(song): void  // add next
    addToEnd(song): void    // add at end
}

class PlaybackController {
    queue: PlayQueue
    isPlaying: boolean
    currentPosition: int  // seconds into current song

    play(): void
    pause(): void
    next(): void -> queue.next(); play()
    previous(): void -> if (currentPosition > 3) restart() else queue.previous()
    seek(position): void
    setRepeatMode(mode): void
    toggleShuffle(): void
}

class User {
    id: String
    name: String
    library: UserLibrary
    playlists: List<Playlist>
    listeningHistory: List<ListeningRecord>
}

class UserLibrary {
    likedSongs: Set<Song>
    savedAlbums: Set<Album>
    followedArtists: Set<Artist>
    followedPlaylists: Set<Playlist>
}

interface RecommendationStrategy {
    recommend(user: User): List<Song>
}

class GenreBasedRecommendation implements RecommendationStrategy {
    recommend(user):
        topGenres = user.listeningHistory.groupBy(genre).sortByCount().top(3)
        return findPopularSongsInGenres(topGenres).notIn(user.listeningHistory)
}
```

### Key Design Decisions
1. PlayQueue maintains both original and shuffled order for unshuffle support
2. Iterator-like pattern in PlayQueue handles next/prev/shuffle/repeat modes
3. Playlist followers notified via Observer when songs added/removed
4. "Previous" restarts current song if > 3 seconds in (Spotify-like behavior)
5. Listening history drives recommendations via Strategy pattern
6. UserLibrary separates liked songs from created playlists

